    reason="Un-evaluated annotations only exist on Python 3.14+",
)
def test_class_var_forward_reference(self, slots):
    """
    ClassVars are recognized even if their annotation is a forward
    reference that can't be evaluated -- for example because ClassVar is
    only imported inside an `if TYPE_CHECKING` block.
    """

    @attr.s(auto_attribs=True, slots=slots)
    class C:
        cls_var1: ClassVar[int]
        cls_var2: "ClassVar[int]" = 42
        cls_var3: "t.ClassVar[int]" = {}
        a: int

    assert ["a"] == [a.name for a in attr.fields(C)]
    assert 23 == C(23).a

@pytest.mark.skipif(
    sys.version_info < (3, 14),
    reason="Un-evaluated annotations only exist on Python 3.14+",
)
def test_forward_reference_fields(self):
    """
    Fields whose annotations are forward references that can't be
    evaluated are still turned into fields.
    """

    @attr.s(auto_attribs=True)
    class C:
        cls_var: ClassVar[int]
        x: NonExistent  # noqa: F821

    assert ["x"] == [a.name for a in attr.fields(C)]

    with pytest.raises(NameError):
        attr.resolve_types(C)

