def _get_class_annotations(klass: type) -> Mapping[str, Any]:
    """
    Return the annotations declared directly on the given class.

    Class level annotations are not inherited, but they may be stored lazily
    (PEP 649), in which case they cannot always be evaluated.

    """
    annotations = klass.__dict__.get("__annotations__")
    if annotations is None:
        try:
            annotations = klass.__annotations__
        except NameError:
            # The annotations could not be evaluated, but that shouldn't stop us from
            # checking whether the attribute is declared on the class
            return {}

    return annotations


def _declares_class_member(klass: type, attrname: str) -> bool:
    """
    Check whether the given class, or any of its base classes, declares an attribute
    called ``attrname`` for its instances.

    Instance attributes are not visible on a class object, as they only exist on the
    instances, so they have to detected from the declarations (annotations,
    ``__slots__``) or from the assignments to ``self`` in the class body.

    """
    for base in klass.__mro__:
        class_dict = base.__dict__
        if attrname in _get_class_annotations(base):
            return True

        slots = class_dict.get("__slots__")
        if isinstance(slots, str):
            slots = (slots,)

        if attrname in (slots or ()):
            return True

        # Names statically accessed on ``self`` in the class body (PEP 649)
        static_attributes = class_dict.get("__static_attributes__")
        if static_attributes is not None:
            if attrname in static_attributes:
                return True
        else:
            # Python 3.12 and earlier have no __static_attributes__, so the attribute
            # names used in the class body have to retrieved from the byte code of the
            # functions defined in it
            for member in class_dict.values():
                if isinstance(member, (classmethod, staticmethod, property)):
                    member = getattr(member, "__func__", None) or member.fget

                code = getattr(member, "__code__", None)
                if code is not None and attrname in code.co_names:
                    return True

    return False


