@staticmethod
def _needs_line_break(cur: str, item: Item) -> bool:
    """Whether the given item needs to be separated from the already
    rendered ``cur`` by a newline.

    Items are rendered one per line, so an item must never be appended
    directly to a line that is still open. That happens whenever the item
    rendered last did not end with its terminating newline, which is the
    case for the last item of a document (or of a dotted key line) that
    has no trailing newline in its source.
    """
    stripped = cur.strip(" ")
    if not stripped or stripped.endswith("\n"):
        return False

    if isinstance(item, Null):
        return False

    if isinstance(item, (Comment, Whitespace)):
        # These items render their own leading whitespace, which usually
        # already starts a new line.
        return "\n" not in item.as_string()

    return "\n" not in item.trivia.indent

def as_string(self) -> str:
    """Render as TOML string."""
    s = ""
    for k, v in self._body:
        if self._needs_line_break(s, v):
            s += "\n"

        if k is not None:
            if isinstance(v, Table):
                s += self._render_table(k, v)
            elif isinstance(v, AoT):
                s += self._render_aot(k, v)
            else:
                s += self._render_simple_item(k, v)
        else:
            s += self._render_simple_item(k, v)

    return s

